  const outcome = { ...unsigned, outcomeSha256: m80HostedSha256(m80HostedCanonicalJson(unsigned)) } as unknown as M80HostedOutcome
  return { ...chain, outcome, outcomePin: artifactPin(chain.outcomePin.path, outcome) }
}

